package com.aliothmoon.maafw.once;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
import com.aliothmoon.maafw.rewards.RewardRegionLocator;
/** Static synthetic literals only; these cases do not recover or attribute the v37 frame. */
public class UniqueVetoRuleTest {
 static LiveRewardCardObservation.Frame f(List<FrameStructureEvidence.Line> rows){return UniquePendingBusinessTest.frame(UniquePendingBusinessTest.beforePixels(),rows,false);}
 static List<FrameStructureEvidence.Line> titled(String text){var rows=UniquePendingBusinessTest.beforeRows();UniquePendingBusinessTest.title(rows,text,.99);return rows;}
 static void u(List<FrameStructureEvidence.Line> rows,String text,int top){rows.add(IndependentCurrentCardTest.r(text,.99,150,top,280,top+20));}
 @Test public void ordinaryShortWordsOrCjkPartsAreNotConsumedLabels(){for(String word:List.of("the","your","on","with","test","daily","knowledge","questions","yourself","challenge","Check","签","到","每日")){var rows=UniquePendingBusinessTest.beforeRows();u(rows,word,1370);var result=f(rows);assertTrue(word+" "+result.uniqueEvidenceSummary(),result.uniqueBefore());assertEquals(RewardRegionLocator.VetoRule.NOT_APPLICABLE,result.uniqueVetoDiagnostic().rule());}}
 @Test public void lowOrdinaryWordStillFailsConfidenceNotConsumed(){for(String word:List.of("the","your","on","with","knowledge","questions","签","到","每日")){var rows=UniquePendingBusinessTest.beforeRows();rows.add(IndependentCurrentCardTest.r(word,.1,150,1370,280,1390));var result=f(rows);assertFalse(result.uniqueBefore());assertTrue(result.uniqueEvidenceSummary().contains("uniqueFirstGate=ROW_LOW_CONFIDENCE"));assertEquals(RewardRegionLocator.VetoRule.NOT_APPLICABLE,result.uniqueVetoDiagnostic().rule());}}
 @Test public void checkInsideAnotherTitleIsNotCheckIn(){for(String title:List.of("Check your facts","Check","Quote this sentence")){var result=f(titled(title));assertTrue(title+" "+result.uniqueEvidenceSummary(),result.uniqueBefore());}}
 @Test public void fullConsumedTitlesBodiesAndCategoryLabelsRemainBanned(){String[][] cases={{"Do you know the answer?","TRIVIA_TITLE"},{"Challenge yourself with these trivia questions","TRIVIA_BODY_A"},{"Test your knowledge on these topics","TRIVIA_BODY_B"},{"Quote of the day - extra","QUOTE"},{"Complete this puzzle now","PUZZLE"},{"每日签到奖励","CHECKIN"},{"Quote!","QUOTE"},{"ＱＵＯＴＥ","QUOTE"},{"Puzzle?","PUZZLE"},{"签到","CHECKIN"},{"Check-in","CHECKIN"},{"Check-in rewards","CHECKIN"},{"Daily check‑in reward","CHECKIN"}};
  for(String[] c:cases){var result=f(titled(c[0]));assertFalse(result.uniqueBefore());assertEquals(c[1],result.uniqueVetoDiagnostic().category().name());assertEquals(RewardRegionLocator.VetoAssembly.SINGLE_ROW,result.uniqueVetoDiagnostic().assembly());assertTrue(result.uniqueEvidenceSummary().contains("uniqueFirstGate=CONSUMED_CATEGORY"));}}
 @Test public void originalStrictFragmentsRemainVetoes(){for(String part:List.of("Do you know the","answer?","Challenge yourself with","these trivia questions","Test your knowledge on","your knowledge","these trivia","these topics")){var result=f(titled(part));assertFalse(result.uniqueBefore());assertEquals(part,RewardRegionLocator.VetoRule.STRICT_FRAGMENT,result.uniqueVetoDiagnostic().rule());}}
 @Test public void fullSplitTitleAndBodyRemainHeld(){for(String[] c:new String[][]{{"Do you know the","answer?"},{"Challenge yourself with","these trivia questions"},{"Test your knowledge on","these topics"}}){var rows=titled(c[0]);IndependentCurrentCardTest.replace(rows,1245,c[1],.99);assertFalse(f(rows).uniqueBefore());}}
 @Test public void exactSplitCheckInAndChineseCheckInRetainOriginalParts(){for(boolean chinese:new boolean[]{false,true}){var rows=UniquePendingBusinessTest.beforeRows();u(rows,chinese?"签":"Check",1330);u(rows,chinese?"到":"in",1360);var result=f(rows);var d=result.uniqueVetoDiagnostic();assertFalse(result.uniqueBefore());assertEquals(RewardRegionLocator.VetoCategory.CHECKIN,d.category());assertEquals(RewardRegionLocator.VetoAssembly.ADJACENT_ROWS,d.assembly());assertEquals(2,d.parts().size());assertEquals(new RewardRegionLocator.Box(150,1330,280,1350),d.parts().get(0).box());assertEquals(.99,d.parts().get(0).confidence(),0);}}
 @Test public void nonadjacentConservativePairIsLabeledNonadjacent(){var rows=UniquePendingBusinessTest.beforeRows();u(rows,"Check",1330);u(rows,"ordinary",1360);u(rows,"in",1390);var result=f(rows);assertFalse(result.uniqueBefore());assertEquals(RewardRegionLocator.VetoCategory.CHECKIN,result.uniqueVetoDiagnostic().category());assertEquals(RewardRegionLocator.VetoAssembly.NONADJACENT_ROWS,result.uniqueVetoDiagnostic().assembly());}
 @Test public void composedLoginRiskIsNeverReportedAsConsumedCategory(){var rows=UniquePendingBusinessTest.beforeRows();u(rows,"Sign",1330);u(rows,"in",1360);var result=f(rows);assertFalse(result.uniqueBefore());var d=result.uniqueVetoDiagnostic();assertEquals(RewardRegionLocator.VetoRule.RISK_PATTERN,d.rule());assertEquals(RewardRegionLocator.VetoCategory.RISK,d.category());assertEquals(RewardRegionLocator.VetoAssembly.ADJACENT_ROWS,d.assembly());assertTrue(result.uniqueEvidenceSummary().contains("uniqueFirstGate=EXTRA_STEP_RISK"));assertFalse(result.uniqueEvidenceSummary().contains("uniqueFirstGate=CONSUMED_CATEGORY"));}
 @Test public void diagnosticsAreBoundedImmutableAndNeverContainOcrWords(){var rows=UniquePendingBusinessTest.beforeRows();u(rows,"Check",1330);u(rows,"in",1360);var result=f(rows);var d=result.uniqueVetoDiagnostic();assertFalse(d.toString().contains("Check"));assertFalse(d.toString().contains("knowledge"));assertFalse(d.toString().contains("Unmodeled card"));assertTrue(d.parts().size()<=6);assertTrue(d.toString().length()<1400);assertThrows(UnsupportedOperationException.class,()->d.parts().clear());
  for(var field:RewardRegionLocator.VetoPart.class.getDeclaredFields())assertTrue(field.getType()==RewardRegionLocator.Box.class||field.getType()==double.class);
  for(var field:RewardRegionLocator.VetoDiagnostic.class.getDeclaredFields())assertTrue(field.getType().isEnum()||field.getType()==List.class);
 }
}
